export type Platform = {
  id: string;
  name: string;
};

type Rule = {
  id: string;
  name: string;
  test: (value: string) => boolean;
};

const includes = (pattern: RegExp) => (value: string) => pattern.test(value);

function mentionsCss(value: string): boolean {
  const cleaned = value.replace(/scss/gi, ' ').replace(/css\s+animations/gi, ' ');
  return /\bcss3?\b/i.test(cleaned);
}

