const EXTRAS: { name: string; pattern: RegExp }[] = [];

export function platformsFor(labels: string[], summary = ''): Platform[] {
  const corpus = summary ? [...labels, summary] : [...labels];
  const found: Platform[] = [];
  for (const rule of RULES) {
    if (!corpus.some((value) => rule.test(value))) continue;
    found.push({ id: rule.id, name: rule.name });
  }
  return found;
}

export function unmatched(labels: string[]): string[] {
  const found: string[] = [];
  const seen = new Set<string>();
  for (const label of labels) {
    for (const extra of EXTRAS) {
      if (seen.has(extra.name) || !extra.pattern.test(label)) continue;
      seen.add(extra.name);
      found.push(extra.name);
    }
  }
  return found;
}

const USE: Record<string, string> = {
  wordpress: 'site',
  'wordpress-vip': 'host',
  css: 'interface',
  lottie: 'motion',
  php: 'theme',
  aws: 'host',
  drupal: 'site',
  react: 'app',
  angular: 'app',
  vue: 'app',
  node: 'server',
  typescript: 'app',
  javascript: 'interface',
  python: 'automation',
  ruby: 'app',
  craft: 'site',
  webflow: 'site',
  vercel: 'host',
  'cloudflare-workers': 'host',
  'cloudflare-pages': 'host',
  next: 'app',
  svelte: 'app',
  ember: 'app',
  astro: 'site',
};

export function platformUse(id: string, summary = '', labels: string[] = []): string {
  const blob = `${summary} ${labels.join(' ')}`;
  if (id === 'wordpress' && /theme/i.test(blob)) return 'theme';
  if (id === 'wordpress' && /multisite/i.test(blob)) return 'multisite';
  if ((id === 'vercel' || id === 'aws' || id === 'wordpress-vip') && /host|hosted|hosting|vip/i.test(blob)) return 'host';
  return USE[id] ?? 'stack';
}

export function platformShortName(id: string, name: string): string {
  if (id === 'craft') return 'Craft';
  return name;
}

