/** Icon for one stack item: its platform mark, else a tool mark, else ''. */
export function toolMarkup(name: string): string {
  const platform = platformMarks([name])[0];
  if (platform) return platform.svg;
  const tool = TOOL_MARKS.find((entry) => entry.pattern.test(name));
  return tool ? `<svg viewBox="0 0 24 24" aria-hidden="true">${tool.mark}</svg>` : '';
}

export function platformMarks(labels: string[]): { id: string; name: string; svg: string }[] {
  return platformsFor(labels)
    .map((platform) => ({ ...platform, svg: platformMarkup(platform.id) }))
    .filter((platform) => platform.svg);
}
